/* Janela de leitura.
   A Base devolve no máximo 100 pedidos por chamada, ordenados pela data de
   confirmação. Em vez de paginar (mais nós, mais coisa para quebrar), a
   leitura é uma janela curta que roda de hora em hora: o que entrou nas
   últimas 72h é relido e regravado por cima. Regravar não custa nada — a
   gravação é por id, então o mesmo pedido só sobrescreve a si mesmo.

   Para trazer o histórico na primeira vez, aumente DIAS aqui, rode à mão
   quantas vezes precisar, e devolva para 3. */
const DIAS = 3;
const desde = Math.floor((Date.now() - DIAS * 864e5) / 1000);
return [{ json: { desde, dias: DIAS } }];

/* Fica só o que é WhatsApp e traduz para o formato do LiveOps.

   O nome da origem PRECISA ser confirmado antes de ligar isto em produção —
   rode o nó "Origens de venda" uma vez e ponha aqui o que ele devolver. Com
   a lista errada, a aba "Pedidos Base WhatsApp" passa a mostrar pedido de
   marketplace, que é pior do que não mostrar nada: a equipe age em cima de
   um dado que diz uma coisa e é outra. */
const ORIGENS_WHATSAPP = ['whatsapp', 'personal', 'pessoal'];  // ← confirmar

const resp = $input.first().json || {};
if (resp.status && resp.status !== 'SUCCESS') {
  throw new Error('A Base recusou a leitura: ' + (resp.error_message || resp.error_code || JSON.stringify(resp).slice(0, 200)));
}
const pedidos = resp.orders || [];

// Nome do status: a Base manda o número, e número não diz nada na tela
const nomeStatus = {};
try {
  const lista = $('Status da Base').first().json.statuses || [];
  lista.forEach(s => { nomeStatus[String(s.id)] = s.name || s.name_for_customer || ''; });
} catch (e) { /* sem a lista, mostra o número mesmo */ }

const TZ = 'America/Sao_Paulo';
function data(ts) {
  if (!ts) return '';
  const d = new Date(Number(ts) * 1000);
  const p = new Intl.DateTimeFormat('sv-SE', { timeZone: TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
  return p; // sv-SE já sai como AAAA-MM-DD
}
function hora(ts) {
  if (!ts) return '';
  return new Intl.DateTimeFormat('pt-BR', { timeZone: TZ, hour: '2-digit', minute: '2-digit' }).format(new Date(Number(ts) * 1000));
}

/* O total não vem pronto: a Base entrega os produtos e o frete separados.
   Somar aqui evita que a tela mostre um valor diferente do que a Base
   mostra — que seria o tipo de divergência que ninguém consegue explicar
   depois. */
function total(p) {
  const itens = (p.products || []).reduce((a, i) =>
    a + (Number(i.price_brutto) || 0) * (Number(i.quantity) || 0), 0);
  return Math.round((itens + (Number(p.delivery_price) || 0)) * 100) / 100;
}

const carimbo = new Date().toLocaleString('pt-BR', {
  timeZone: TZ, day: '2-digit', month: '2-digit', year: 'numeric',
  hour: '2-digit', minute: '2-digit'
});

const saida = [];
let doWhats = 0;
for (const p of pedidos) {
  const origem = String(p.order_source || '').toLowerCase();
  const nomeOrigem = String(p.order_source_info || '').toLowerCase();
  const ehWhats = ORIGENS_WHATSAPP.some(o => origem === o || nomeOrigem.includes(o));
  if (!ehWhats) continue;
  doWhats++;

  const quando = p.date_confirmed || p.date_add;
  saida.push({ json: {
    chave: 'base_' + p.order_id,
    patch: {
      id: 'base_' + p.order_id,
      numero: String(p.order_id),
      externo: String(p.external_order_id || p.shop_order_id || ''),
      cliente: p.delivery_fullname || p.invoice_fullname || p.user_login || '',
      telefone: String(p.phone || '').replace(/\D/g, ''),
      valor: total(p),
      status: nomeStatus[String(p.order_status_id)] || ('status ' + p.order_status_id),
      canal: p.order_source_info || p.order_source || 'WhatsApp',
      data: data(quando),
      hora: hora(quando),
      link: 'https://panel-u.baselinker.com/orders.php#order:' + p.order_id,
      sincronizadoEm: carimbo,
      _by: 'n8n'
    }
  }});
}

console.log(pedidos.length + ' pedido(s) na janela · ' + doWhats + ' do WhatsApp');
if (pedidos.length >= 100) {
  console.log('ATENÇÃO: a Base devolveu 100, que é o máximo por chamada. Encurte DIAS na Janela de leitura, senão os mais antigos ficam de fora.');
}
return saida;
